using System.ComponentModel.DataAnnotations;
namespace RaceDay.Mvc.Models;
public class LoginVm { [Required,EmailAddress] public string Email {get;set;}=""; [Required] public string Password {get;set;}=""; }
public class RegisterVm { [Required] public string FirstName {get;set;}=""; [Required] public string LastName {get;set;}=""; [Required,EmailAddress] public string Email {get;set;}=""; [Required,MinLength(8)] public string Password {get;set;}=""; [Required] public string Role {get;set;}="Participant"; public string? Phone {get;set;} }
public class EventVm { public int EventId {get;set;} [Required, StringLength(150,MinimumLength=2)] public string EventName {get;set;}=""; public string? Description {get;set;} public DateTime EventDate {get;set;}=DateTime.Today.AddDays(7); public TimeSpan StartTime {get;set;}=new(7,0,0); [Required] public string Venue {get;set;}=""; [Required] public string Location {get;set;}=""; [Range(1,100000)] public int MaxParticipants {get;set;}=100; public string Status {get;set;}="Open"; public string EventType {get;set;}="Run"; public string? BannerImageUrl {get;set;} public int OrganizerId {get;set;} }
public class CategoryVm { public int CategoryId {get;set;} [Required] public string CategoryName {get;set;}=""; public string? Description {get;set;} public int MinAge {get;set;} public int MaxAge {get;set;}=120; public decimal? DistanceKm {get;set;} public int MaxParticipants {get;set;}=100; public decimal EntryFee {get;set;} }
public class EventDetailsVm : EventVm { public List<CategoryVm> Categories {get;set;}=[]; }
public class EnrolmentVm { public int EnrolmentId {get;set;} public int EventId {get;set;} public string EventName {get;set;}=""; public int CategoryId {get;set;} public string CategoryName {get;set;}=""; public string Status {get;set;}=""; public DateTime EnrolmentDate {get;set;} public string Participant {get;set;}=""; public string Email {get;set;}=""; public int? FinishPosition {get;set;} public TimeSpan? FinishTime {get;set;} public string ResultStatus {get;set;}="Pending"; }
public class ResultVm { public int EnrolmentId {get;set;} public string EventName {get;set;}=""; public DateTime EventDate {get;set;} public string CategoryName {get;set;}=""; public int? FinishPosition {get;set;} public TimeSpan? FinishTime {get;set;} public string ResultStatus {get;set;}="Pending"; public string PositionLabel {get;set;}="—"; }
public class ProfileVm { public int UserId {get;set;} public string FirstName {get;set;}=""; public string LastName {get;set;}=""; public string Email {get;set;}=""; public string Role {get;set;}=""; public string? Phone {get;set;} public string? ProfileImageUrl {get;set;} }
